<?php require 'config.php'; if(isLoggedIn()){header('Location: index.php');exit;} $error='';$success='';
if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$pw=$_POST['password']??'';$cp=$_POST['confirm_password']??'';
if($name===''||$email===''||$pw===''||$cp==='')$error='Please complete all required fields.';elseif(!filter_var($email,FILTER_VALIDATE_EMAIL)||!preg_match('/^[^@\s]+@[^@\s]+\.[^@\s]+$/',$email))$error='Please enter a valid email address.';elseif(!preg_match('/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d).{8,}$/',$pw))$error='Password must be 8+ characters with uppercase, lowercase and a number.';elseif($pw!==$cp)$error='Passwords do not match.';else{$st=$conn->prepare('SELECT id FROM users WHERE email=? LIMIT 1');$st->bind_param('s',$email);$st->execute();$st->store_result();if($st->num_rows)$error='Registration could not be completed. Please use another email.';else{$hash=password_hash($pw,PASSWORD_BCRYPT);$ins=$conn->prepare("INSERT INTO users(name,email,password,role) VALUES(?,?,?,'user')");$ins->bind_param('sss',$name,$email,$hash);if($ins->execute()){$success='Registration successful. Redirecting you to login...';header('Refresh:2; url=login.php');}else $error='Registration could not be completed.';$ins->close();}$st->close();}}
$pageTitle='Create Account | Ceylon Noir';require 'header.php';?>
<section class="auth-page"><div class="auth-card"><span class="gold-kicker">BECOME A MEMBER</span><h1>Create your account</h1><p class="muted">Join Ceylon Noir and manage your orders, profile and saved delivery details.</p><?php if($error):?><div class="alert"><?php echo e($error);?></div><?php endif;?><?php if($success):?><div class="success"><?php echo e($success);?></div><?php endif;?><form method="post"><label>Full Name</label><input name="name" required><label>Email</label><input type="email" name="email" required><label>Password</label><input type="password" name="password" minlength="8" required><small class="field-help">8+ characters, uppercase, lowercase and number.</small><label>Confirm Password</label><input type="password" name="confirm_password" minlength="8" required><button class="gold-btn full" type="submit">CREATE ACCOUNT</button></form><p class="auth-foot">Already a member? <a class="gold-link" href="login.php">Sign in</a></p></div></section><?php require 'footer.php';?>
